   public static int getCodigoArquivoA(String arquivo) {
      arquivo = arquivo.split("\\.")[0];
      int saida = 0;

      for(int i = 0; i < nomesTabelasA.length; ++i) {
         if (arquivo.equalsIgnoreCase(nomesTabelasA[i])) {
            saida = i;
         }
      }

      return saida;
   }

