   public static int colAparaColB(int tabelaA, int colunaA) {
      int resultado = -1;
      String campoA = camposTabelasA[tabelaA][colunaA];
      int colunaB = 0;

      for(String campoB : camposTabelasB[tabelaA]) {
         if (campoA.equalsIgnoreCase(campoB)) {
            resultado = colunaB;
         }

         ++colunaB;
      }

      return resultado;
   }

